// src/hooks/UseWatchedFolders.js
import { useCallback, useEffect, useState } from 'react';
import { get, post, del } from '../api/HttpClient';

const STORAGE_KEY = 'watchservice.watchedFolders';

function saveLocal(folders) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(folders));
  } catch {}
}

function loadLocal() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function useWatchedFolders() {
  const [folders, setFolders] = useState(loadLocal());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const server = await get('/settings/folders');
      const list = Array.isArray(server) ? server : [];
      setFolders(list);
      saveLocal(list);
    } catch (e) {
      // 서버 실패 시 로컬 유지
      setError(e);
      const local = loadLocal();
      setFolders(local);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const addFolderByPath = useCallback(async (path, name) => {
    const p = String(path || '').trim();
    if (!p) return;

    const folderName = String(name || '').trim() || p.split(/[/\\]/).filter(Boolean).pop() || '폴더';

    try {
      const created = await post('/settings/folders', { name: folderName, path: p });
      const next = [created, ...folders].filter(Boolean);
      setFolders(next);
      saveLocal(next);
    } catch (e) {
      // 서버 실패 시 로컬로라도 추가
      const localId = Date.now();
      const next = [{ id: localId, name: folderName, path: p }, ...folders];
      setFolders(next);
      saveLocal(next);
      setError(e);
    }
  }, [folders]);

  const promptAndAddFolder = useCallback(async () => {
    const path = window.prompt('감시할 폴더 경로를 입력하세요.\n예) C:\\Users\\me\\Desktop');
    if (!path) return;
    await addFolderByPath(path);
  }, [addFolderByPath]);

  const removeFolder = useCallback(async (id) => {
    if (id === undefined || id === null) return;

    // optimistic
    const prev = folders;
    const next = prev.filter((f) => f.id !== id);
    setFolders(next);
    saveLocal(next);

    try {
      await del(`/settings/folders/${id}`);
    } catch (e) {
      // rollback
      setFolders(prev);
      saveLocal(prev);
      setError(e);
    }
  }, [folders]);

  return {
    folders,
    loading,
    error,
    refresh,
    setFolders, // 필요시
    addFolderByPath,
    promptAndAddFolder,
    removeFolder,
  };
}
